-- Foróige projects from Facebook posts (Bailieborough bench, Cootehill workshop).
-- Images must be uploaded to the R2 media bucket under projects/ first (see migrations/README.md).

INSERT OR IGNORE INTO projects (id, slug, date, title, subtitle, description, image, facebook, sort_order, is_draft)
VALUES ('project-7', 'foroige-bailieborough-bench', '10 November 2026', 'Outdoor Bench with Foróige Bailieborough', 'Young people built an outdoor timber bench from the ground up', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Another project completed in Bailieborough, Co. Cavan. We had a great day working alongside the young people from Foróige, building an outdoor timber bench from the ground up."}]},{"type":"paragraph","content":[{"type":"text","text":"The young people got properly involved in the build, from putting the frames together and using the tools, right through to assembling the finished bench. It''s always great to see a project go from a pile of timber to something practical that can be used and enjoyed for years to come."}]},{"type":"paragraph","content":[{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/bailieborough-bench-frames.jpg","alt":"A young person screwing together a timber bench frame beside raised garden beds","width":240}},{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/bailieborough-bench-legs.jpg","alt":"A young person squaring up the timber legs of the bench","width":240}},{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/bailieborough-bench-team.jpg","alt":"A facilitator and a young person assembling the bench frames outdoors","width":240}}]},{"type":"paragraph","content":[{"type":"text","text":"A big thank you to Cavan and Monaghan ETB (CMETB) for funding the project and to Foróige for working with us to make it happen."}]},{"type":"paragraph","content":[{"type":"text","text":"We''d also like to wish Ciara from Foróige all the very best as she moves on to complete her Master''s. Ciara has been a great person to work alongside and a fantastic addition to the projects we''ve been involved in. She''ll definitely be missed, but we wish her every success with her studies and whatever comes next."}]},{"type":"paragraph","content":[{"type":"text","text":"Building Skills, Building Community.","marks":[{"type":"italic"}]}]}]}', 'https://media.letsgiveback.ie/projects/bailieborough-bench-build.jpg', '', (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM projects), 0);

INSERT OR IGNORE INTO projects (id, slug, date, title, subtitle, description, image, facebook, sort_order, is_draft)
VALUES ('project-8', 'foroige-cootehill-workshop', '10 November 2026', 'Woodwork Workshop with Foróige Cootehill', 'Bird boxes, a bird table and a football kit storage box, designed and built by young people', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Another brilliant hands-on project with the young people from Foróige Cootehill, funded by Cavan and Monaghan ETB (CMETB)."}]},{"type":"paragraph","content":[{"type":"text","text":"The lads got stuck into designing and building their own projects, learning practical skills and getting experience using tools along the way. Most of the group worked on building bird boxes, while one young lad had his own idea and decided to build a football kit storage box instead."}]},{"type":"paragraph","content":[{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/cootehill-bird-boxes.jpg","alt":"Two people drilling timber bird box parts on a workbench","width":240}},{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/cootehill-bird-table.jpg","alt":"A finished handmade timber bird table","width":240}},{"type":"image","attrs":{"src":"https://media.letsgiveback.ie/projects/cootehill-kit-box.jpg","alt":"A young person building a large timber football kit storage box with a facilitator","width":240}}]},{"type":"paragraph","content":[{"type":"text","text":"That''s a big part of what we want these workshops to be about: giving young people the opportunity to come up with an idea, work through it, learn new skills and see something they''ve made with their own hands at the end of it."}]},{"type":"paragraph","content":[{"type":"text","text":"A big thanks to Foróige Cootehill for having us and to CMETB for funding and supporting the programme. Plenty of measuring, drilling, cutting and problem-solving, and some great finished pieces to show for it."}]},{"type":"paragraph","content":[{"type":"text","text":"Building Skills, Building Community.","marks":[{"type":"italic"}]}]}]}', 'https://media.letsgiveback.ie/projects/cootehill-drilling.jpg', '', (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM projects), 0);
